    fn computeEmbeddings(self: *PFRRuntime, tokens: []const u32, embeddings: []f32) !void {
        const embedding_dim = 4096;
        var prng = std.rand.DefaultPrng.init(12345);
        const random = prng.random();

        for (tokens, 0..) |token, i| {
            const start_idx = i * embedding_dim;
            const end_idx = start_idx + embedding_dim;

            prng.seed(@as(u64, token));
            for (embeddings[start_idx..end_idx]) |*emb| {
                emb.* = random.floatNorm(f32) * 0.1;
            }
        }

        if (self.config.sparsification_enabled) {
            try self.applySparsification(embeddings, 0.05);
        }
