    fn computeAttention(self: *PFRRuntime, embeddings: []const f32, output: []f32) !void {
        const seq_len = embeddings.len / 4096;
        const head_dim = 64;
        const num_heads = 64;

        var query = try self.allocator.alloc(f32, embeddings.len);
        defer self.allocator.free(query);
        var key = try self.allocator.alloc(f32, embeddings.len);
        defer self.allocator.free(key);
        var value = try self.allocator.alloc(f32, embeddings.len);
        defer self.allocator.free(value);

        @memcpy(query, embeddings);
        @memcpy(key, embeddings);
        @memcpy(value, embeddings);

        for (0..num_heads) |head| {
            const head_start = head * head_dim;
            const head_end = head_start + head_dim;

            for (0..seq_len) |i| {
                for (0..seq_len) |j| {
                    var dot_product: f32 = 0.0;

                    for (head_start..head_end) |dim| {
                        const q_idx = i * 4096 + dim;
                        const k_idx = j * 4096 + dim;
                        dot_product += query[q_idx] * key[k_idx];
                    }

                    const attention_weight = dot_product / @sqrt(@as(f32, @floatFromInt(head_dim)));

                    for (head_start..head_end) |dim| {
                        const v_idx = j * 4096 + dim;
                        const out_idx = i * 4096 + dim;
                        output[out_idx] += attention_weight * value[v_idx];
                    }
                }
            }
        }

        if (self.config.state_compression) {
            try self.compressAttentionOutput(output);
        }
    }

    fn updateSSMStates(self: *PFRRuntime, input: []const f32) !void {
        const state_dim = 4096;
        const seq_len = input.len / state_dim;

        for (0..seq_len) |t| {
            const input_slice = input[t * state_dim..(t + 1) * state_dim];
            const state = self.ssm_states[t % self.ssm_states.len];

            const A = 0.9;
            const B = 0.1;

            for (state, input_slice) |*s, inp| {
