        defer self.allocator.free(routing_weights);

        for (self.expert_weights, routing_weights, 0..) |expert, *weight, i| {
            var dot_product: f32 = 0.0;

            for (input[0..@min(input.len, expert.len)], expert[0..@min(input.len, expert.len)]) |inp, exp| {
                dot_product += inp * exp;
            }

            weight.* = dot_product / (input_norm + 1e-8);

            if (i >= 8) weight.* *= 0.1;
        }

        const indices = try self.selectTopK(routing_weights, 8);
        defer self.allocator.free(indices);

        for (expert_outputs, indices) |expert_out, expert_idx| {
            const expert = self.expert_weights[expert_idx];
            const weight = routing_weights[expert_idx];

            for (expert_out, expert) |*out, exp| {
                out.* = weight * exp * @tanh(exp);
            }
        }

        if (self.config.rule_driven_decider) {
            try self.applyRuleDrivenDecisions(expert_outputs);
        }
