        for (expert_outputs, 0..) |expert_out, expert_idx| {
            const expert_weight = 1.0 / @as(f32, @floatFromInt(expert_outputs.len));

            for (logits, 0..) |*logit, vocab_idx| {
                const feature_idx = vocab_idx % expert_out.len;
                logit.* += expert_weight * expert_out[feature_idx];
            }
