    fn sampleTokens(self: *PFRRuntime, logits: []const f32, max_length: usize) ![]u32 {
        var tokens = try self.allocator.alloc(u32, max_length);
        var prng = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.timestamp())));
        const random = prng.random();

        for (tokens, 0..) |*token, i| {
            if (i == 0) {
                token.* = self.sampleFromDistribution(logits, random);
            } else {
                const previous_logits = try self.allocator.alloc(f32, logits.len);
                defer self.allocator.free(previous_logits);

                @memcpy(previous_logits, logits);

