    fn applyLowRankUpdate(self: *PFRRuntime, state: []f32, rank: u32) !void {
        _ = self;

        const effective_rank = @min(rank, @as(u32, @intCast(state.len)));

        var u = try self.allocator.alloc(f32, effective_rank);
        defer self.allocator.free(u);
        var v = try self.allocator.alloc(f32, effective_rank);
