        for (u, v, 0..) |*u_val, *v_val, i| {
            u_val.* = state[i % state.len];
            v_val.* = state[(i + effective_rank) % state.len];
        }

        for (state, 0..) |*s, i| {
            var update: f32 = 0.0;
            for (u, v) |u_val, v_val| {
                update += u_val * v_val * @sin(@as(f32, @floatFromInt(i)) * 0.01);
            }
            s.* += 0.01 * update;
        }
    }

    fn applyRuleDrivenDecisions(self: *PFRRuntime, expert_outputs: [][]f32) !void {
        _ = self;

        for (expert_outputs, 0..) |expert_out, expert_idx| {
            const rule_factor = switch (expert_idx) {
                0 => 1.2, // Hungarian expert
                5 => 1.1, // Code expert
                6 => 1.15, // Math expert
                else => 1.0,
            };

            for (expert_out) |*output| {
                output.* *= rule_factor;
            }
        }
    }

    fn applyCustomOptimization(self: *PFRRuntime, logits: []f32) !void {
        _ = self;

        const learning_rate = 0.001;

        for (logits, 0..) |*logit, i| {
            const gradient = @sin(@as(f32, @floatFromInt(i)) * 0.01);
            logit.* -= learning_rate * gradient;
        }
    }

    fn computeNorm(self: *PFRRuntime, data: []const f32) f32 {
        _ = self;

        var sum_squares: f32 = 0.0;
        for (data) |value| {
            sum_squares += value * value;
        }
        return @sqrt(sum_squares);
    }

    fn selectTopK(self: *PFRRuntime, weights: []const f32, k: usize) ![]usize {
        var indices = try self.allocator.alloc(usize, weights.len);
        defer self.allocator.free(indices);

        for (indices, 0..) |*idx, i| {
            idx.* = i;
        }

        std.sort.insertion(usize, indices, weights, struct {
            fn lessThan(context: []const f32, a: usize, b: usize) bool {
                return context[a] > context[b];
            }
        }.lessThan);

        const result = try self.allocator.alloc(usize, k);
        @memcpy(result, indices[0..k]);
        return result;
    }

    fn applySoftmax(self: *PFRRuntime, logits: []f32) void {
        _ = self;

        var max_logit: f32 = -std.math.inf(f32);
        for (logits) |logit| {
            max_logit = @max(max_logit, logit);
        }

        var sum_exp: f32 = 0.0;
        for (logits) |*logit| {
            logit.* = @exp(logit.* - max_logit);
            sum_exp += logit.*;
        }

        for (logits) |*logit| {
            logit.* /= sum_exp;
        }
    }

    fn sampleFromDistribution(self: *PFRRuntime, distribution: []const f32, random: std.rand.Random) u32 {
        _ = self;

        const rand_val = random.float(f32);
        var cumulative: f32 = 0.0;

        for (distribution, 0..) |prob, i| {
            cumulative += prob;
            if (rand_val <= cumulative) {
                return @as(u32, @intCast(i));
            }
        }

        return @as(u32, @intCast(distribution.len - 1));
    }
};

