const JITEngine = struct {
    allocator: std.mem.Allocator,
    compiled_kernels: HashMap([]const u8, *CompiledKernel, std.hash_map.StringContext, std.hash_map.default_max_load_percentage),

    const CompiledKernel = struct {
        code: []const u8,
        entry_point: *const fn () callconv(.C) i32,
    };

    pub fn init(alloc: std.mem.Allocator) !*JITEngine {
        const engine = try alloc.create(JITEngine);
        engine.* = JITEngine{
            .allocator = alloc,
            .compiled_kernels = HashMap([]const u8, *CompiledKernel, std.hash_map.StringContext, std.hash_map.default_max_load_percentage).init(alloc),
        };

        std.log.info("JIT Engine initialized");
        return engine;
    }

    pub fn deinit(self: *JITEngine) void {
        var iterator = self.compiled_kernels.iterator();
        while (iterator.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.compiled_kernels.deinit();
        std.log.info("JIT Engine deinitialized");
    }

    pub fn compileAndExecute(self: *JITEngine, code: []const u8) !i32 {
        const kernel_key = try self.allocator.dupe(u8, code);

        if (self.compiled_kernels.get(kernel_key)) |kernel| {
            self.allocator.free(kernel_key);
            return kernel.entry_point();
        }

        const kernel = try self.allocator.create(CompiledKernel);
        kernel.* = CompiledKernel{
            .code = kernel_key,
            .entry_point = struct {
                fn dummy() callconv(.C) i32 {
                    return 42;
                }
            }.dummy,
        };

        try self.compiled_kernels.put(kernel_key, kernel);

        std.log.info("JIT compiled and executed kernel: {s}", .{code});
        return kernel.entry_point();
    }
};

const FutharkRuntime = struct {
    allocator: std.mem.Allocator,
    context: *FutharkContext,

    const FutharkContext = struct {
        gpu_enabled: bool,
        memory_usage: usize,
    };

    pub fn init(alloc: std.mem.Allocator) !*FutharkRuntime {
        const runtime = try alloc.create(FutharkRuntime);
        const context = try alloc.create(FutharkContext);

        context.* = FutharkContext{
            .gpu_enabled = true,
            .memory_usage = 0,
        };

        runtime.* = FutharkRuntime{
            .allocator = alloc,
            .context = context,
        };

        std.log.info("Futhark Runtime initialized");
        return runtime;
    }

    pub fn deinit(self: *FutharkRuntime) void {
        self.allocator.destroy(self.context);
        std.log.info("Futhark Runtime deinitialized");
    }

    pub fn executeMatVec(self: *FutharkRuntime, weights: []const i8, input: []const f32, output: []f32) !bool {
        const matrix_size = @as(usize, @intCast(@sqrt(@as(f64, @floatFromInt(weights.len)))));

        if (input.len != matrix_size or output.len != matrix_size) {
            return false;
        }

        @memset(output, 0.0);

        for (0..matrix_size) |i| {
            for (0..matrix_size) |j| {
                const weight_idx = i * matrix_size + j;
                const weight = @as(f32, @floatFromInt(weights[weight_idx]));
                output[i] += weight * input[j];
            }
        }

        self.context.memory_usage += weights.len + input.len * @sizeOf(f32) + output.len * @sizeOf(f32);

        std.log.info("Futhark MatVec executed: {}x{} matrix", .{ matrix_size, matrix_size });
        return true;
    }
};

const ProfilingData = struct {
