            .total_inferences = 0,
            .total_inference_time = 0.0,
            .total_input_tokens = 0,
            .total_output_chars = 0,
        };
    }

    pub fn recordInference(self: *ProfilingData, duration_ms: f64, input_tokens: usize, output_chars: usize) void {
        self.total_inferences += 1;
        self.total_inference_time += duration_ms;
        self.total_input_tokens += input_tokens;
        self.total_output_chars += output_chars;
    }

    pub fn getAverageLatency(self: *const ProfilingData) f64 {
        if (self.total_inferences == 0) return 0.0;
        return self.total_inference_time / @as(f64, @floatFromInt(self.total_inferences));
    }

    pub fn getThroughput(self: *const ProfilingData) f64 {
        if (self.total_inference_time == 0.0) return 0.0;
        return @as(f64, @floatFromInt(self.total_output_chars)) / (self.total_inference_time / 1000.0);
    }
};

pub extern fn pfr_execute_blitzkriegfuthark_hyperquant_matvec_sparse(weights: []const i8, input: []const f32, output: []f32, rows: usize, cols: usize, sparse: bool) bool {
    if (rows == 0 or cols == 0 or weights.len != rows * cols or input.len != cols or output.len != rows) {
        return false;
    }

    @memset(output, 0.0);

    for (0..rows) |i| {
        for (0..cols) |j| {
            const weight_idx = i * cols + j;
            const weight = @as(f32, @floatFromInt(weights[weight_idx]));

            if (!sparse or @abs(weight) > 0.01) {
                output[i] += weight * input[j];
            }
        }
    }

    if (sparse) {
        for (output) |*out| {
            if (@abs(out.*) < 0.05) {
                out.* = 0.0;
            }
        }
    }

    return true;
}

